const ctx = $('Begin Voiceover').first().json;
const trigger = $('When Executed by Another Workflow').first().json;
const response = $json ?? {};

const body =
  response.body && typeof response.body === 'object'
    ? response.body
    : response;

let statusCode = Number(response.statusCode ?? response.status ?? 0);
const audioBase64 =
  typeof body.audioContent === 'string'
    ? body.audioContent.trim()
    : '';

if (!statusCode && audioBase64) {
  statusCode = 200;
}

const ttsConsumed = statusCode >= 200 && statusCode <= 299;
const base64Shape =
  audioBase64.length > 100 &&
  /^[A-Za-z0-9+/]+={0,2}$/.test(audioBase64);

const ttsSuccess = ttsConsumed && base64Shape;

const providerMessage =
  body?.error?.message ??
  response?.error?.message ??
  response?.message ??
  (ttsConsumed
    ? 'Google Cloud TTS returned no valid MP3 audioContent'
    : 'Google Cloud TTS request failed');

return {
  json: {
    job_id: String(trigger.job_id ?? '').trim(),
    voiceover_run_id: String(ctx.voiceover_run_id ?? '').trim(),
    script_version_id: String(ctx.script_version_id ?? '').trim(),
    target_duration_seconds: Number(ctx.target_duration_seconds),
    locale: String(ctx.locale ?? ''),
    voice_name: String(ctx.voice_name ?? ''),
    sku_family: String(ctx.sku_family ?? ''),
    character_count: Number(ctx.character_count),
    usage_idempotency_key: String(ctx.usage_idempotency_key ?? ''),
    tts_http_status: statusCode,
    tts_consumed: ttsConsumed,
    tts_success: ttsSuccess,
    audio_base64: ttsSuccess ? audioBase64 : '',
    error_message: ttsSuccess ? '' : String(providerMessage).slice(0, 3000),
  },
};

const ctx = $('Normalize TTS Response').first().json;
const response = $json ?? {};

const body =
  response.body && typeof response.body === 'object'
    ? response.body
    : response;

let statusCode = Number(response.statusCode ?? response.status ?? 0);
if (!statusCode && body.status === 'ready') {
  statusCode = 201;
}

const durationMs = Number(body.duration_ms);
const bytes = Number(body.bytes);
const sampleRate = Number(body.sample_rate);
const channels = Number(body.channels);
const sha256 = String(body.sha256 ?? '').trim().toLowerCase();
const codec = String(body.codec ?? '').trim().toLowerCase();
const storagePath = String(body.storage_path ?? '').trim();
const returnedJobId = String(body.job_id ?? '').trim();

const expectedPath =
  '/data/voiceovers/' + ctx.job_id + '/final.mp3';
const targetDurationMs = Math.round(Number(ctx.target_duration_seconds) * 1000);
const durationToleranceMs = Math.max(750, Math.round(targetDurationMs * 0.05)) + 50;
const durationWithinTarget =
  Number.isInteger(durationMs) &&
  Math.abs(durationMs - targetDurationMs) <= durationToleranceMs;

const storeSuccess =
  statusCode === 201 &&
  body.status === 'ready' &&
  returnedJobId === ctx.job_id &&
  storagePath === expectedPath &&
  /^[0-9a-f]{64}$/.test(sha256) &&
  Number.isInteger(bytes) && bytes > 0 &&
  Number.isInteger(durationMs) && durationMs > 0 &&
  durationWithinTarget &&
  Number.isInteger(sampleRate) && sampleRate > 0 &&
  Number.isInteger(channels) && channels > 0 &&
  codec === 'mp3';

const errorMessage =
  !durationWithinTarget && Number.isInteger(durationMs) && durationMs > 0
    ? (
        'voiceover duration outside target tolerance: got ' +
        durationMs + 'ms, target ' + targetDurationMs +
        'ms, tolerance ' + durationToleranceMs + 'ms'
      )
    : (
        body?.message ??
        body?.error ??
        response?.error?.message ??
        response?.message ??
        'media-worker voiceover storage failed'
      );

return {
  json: {
    job_id: ctx.job_id,
    voiceover_run_id: ctx.voiceover_run_id,
    target_duration_seconds: ctx.target_duration_seconds,
    store_success: storeSuccess,
    storage_http_status: statusCode,
    storage_path: storagePath,
    audio_sha256: sha256,
    bytes,
    duration_ms: durationMs,
    target_duration_ms: targetDurationMs,
    duration_tolerance_ms: durationToleranceMs,
    duration_within_target: durationWithinTarget,
    sample_rate: sampleRate,
    channels,
    codec,
    tts_consumed: true,
    error_message: storeSuccess ? '' : String(errorMessage).slice(0, 3000),
  },
};

const ctx = $('Begin Voiceover').first().json;
const source = $json ?? {};
const errorObject =
  source.error && typeof source.error === 'object' && !Array.isArray(source.error)
    ? source.error
    : {};

const candidates = [
  source.error_message,
  errorObject.message,
  source.message,
  source.description,
  typeof source.error === 'string' ? source.error : null,
];

const message = candidates.find(
  (value) => typeof value === 'string' && value.trim().length > 0
) ?? 'unspecified pre-storage M6 failure';

return {
  json: {
    voiceover_run_id: String(ctx.voiceover_run_id ?? '').trim(),
    error_message: ('M6 voiceover failed: ' + message.trim()).slice(0, 4000),
    tts_consumed: source.tts_consumed === true,
  },
};

