if (!statusCode && body.status === 'ready') statusCode = 201;

const jobId = String(trigger.job_id ?? '').trim();
const expectedPath = '/data/voiceovers/' + jobId + '/final.mp3';
const storagePath = String(body.storage_path ?? '').trim();
const returnedJobId = String(body.job_id ?? '').trim();
const sha256 = String(body.sha256 ?? '').trim().toLowerCase();
const bytes = Number(body.bytes);
const durationMs = Number(body.duration_ms);
const sampleRate = Number(body.sample_rate);
const channels = Number(body.channels);
const codec = String(body.codec ?? '').trim().toLowerCase();

const storeSuccess =
  ctx.reuse_candidate === true &&
  statusCode === 201 &&
  body.status === 'ready' &&
  returnedJobId === jobId &&
  storagePath === expectedPath &&
  sha256 === String(ctx.candidate_audio_sha256 ?? '').toLowerCase() &&
  bytes === Number(ctx.candidate_bytes) &&
  durationMs === Number(ctx.candidate_duration_ms) &&
  sampleRate === Number(ctx.candidate_sample_rate) &&
  channels === Number(ctx.candidate_channels) &&
  codec === String(ctx.candidate_codec ?? '').toLowerCase() &&
  /^[0-9a-f]{64}$/.test(sha256) &&
  Number.isInteger(bytes) && bytes > 0 &&
  Number.isInteger(durationMs) && durationMs > 0 &&
  Number.isInteger(sampleRate) && sampleRate > 0 &&
  Number.isInteger(channels) && channels > 0 &&
  codec === 'mp3';

const errorMessage = storeSuccess
  ? ''
  : (
      body?.message ??
      body?.error ??
      response?.error?.message ??
      response?.message ??
      'M5 voiceover candidate promotion failed'
    );

return {json:{
  job_id: jobId,
  voiceover_run_id: String(ctx.voiceover_run_id ?? '').trim(),
  target_duration_seconds: Number(ctx.target_duration_seconds),
  store_success: storeSuccess,
  storage_http_status: statusCode,
  storage_path: storagePath,
  audio_sha256: sha256,
  bytes,
  duration_ms: durationMs,
  sample_rate: sampleRate,
  channels,
  codec,
  tts_consumed: true,
  reused_m5_candidate: true,
  error_message: storeSuccess ? '' : String(errorMessage).slice(0,3000),
}};
